function positionFinish(s){
 const p=POSITION_BOOK[s.role],clubBoost={red:s.role==="上单"||s.role==="中单",black:s.role==="打野",gold:s.role==="辅助",white:s.role==="下路"}[s.team];
 return test(p.finish,p.hint,p.finishWeights,-9,outcome(p.win+" 你们举起了海岬邀请赛奖杯。",[2,2,0,-1],{cup:1,final:"position",positionPlay:s.role}),outcome(p.loss,[1,1,1,0],{final:"positionMiss",positionPlay:s.role}),clubBoost?5:0,clubBoost?teamName(s)+"的队内专项训练":"");
}

