function advanceBonus(s,kind){
 const parts=[];
 if(s.flags.prep===kind)parts.push([10,kind==="hand"?"专项距离训练":"止步口令训练"]);
 if(kind==="call"&&s.flags.partner==="old")parts.push([4,"老搭档的暗号"]);
 if(kind==="hand"&&s.flags.partner==="new")parts.push([3,"新搭档的进攻节奏"]);
 if(kind==="call"&&s.flags.partner==="notes")parts.push([3,"交换过第一视角"]);
 return [parts.reduce((n,[points])=>n+points,0),parts.map(([,why])=>why).join("、")];
}
