function fresh(sex,seed,origin="shop"){
 const s={version:2,account:newAccount(),regional:0,world:0,fit:0,sex,origin,initialSeed:seed>>>0,seed:seed>>>0,turn:1,role:"",team:"",stats:[55,53,52,72],flags:{},titles:0,history:[],pending:null,end:null};
 apply(s,ORIGINS[origin].delta);
 return s;
}
function draw(s){
 s.seed=(s.seed+0x6D2B79F5)>>>0;
 let bits=Math.imul(s.seed^(s.seed>>>15),s.seed|1);
 bits^=bits+Math.imul(bits^(bits>>>7),bits|61);
 return ((bits^(bits>>>14))>>>0)/4294967296;
}
function apply(s,delta){
 const before=s.stats.slice();
 s.stats=s.stats.map((value,i)=>clamp(value+(delta[i]||0),0,100));
 return s.stats.map((v,i)=>v-before[i]);
}
function outcome(text,delta=[],marks={},ending=""){return {text,delta,marks,ending};}
function pick(title,hint,result){return {title,hint,result};}
function test(title,hint,weights,bias,success,failure,bonus=0,reason=""){
 return {title,hint,weights,bias,success,failure,bonus,reason};
}
function chance(s,c){
 const weight=c.weights.reduce((a,b)=>a+b,0);
 const score=s.stats.reduce((v,n,i)=>v+n*(c.weights[i]||0),0)/weight;
 return clamp(Math.round(c.base+(score-60)*0.45+(c.bonus||0)+(c.contest?s.fit:0)),8,93);
}
const scene=(title,body,art,options)=>({title,body,art,options});
const teamName=s=>CLUBS[s.team]?.name||"尚未签约";
function move(s,i){
 if(s.pending||s.end)return false;
 const event=getScene(s), c=event.options[i];
 if(!c)return false;
 const snapshot=sceneRecord(s,event);
 const odds=chance(s,c), roll=1+Math.floor(draw(s)*100);
 const win=roll<=odds, result=win?c.success:c.failure;
 const delta=apply(s,result.delta);
 const {newRole,newTeam,cup,trophy,money,fit,...flags}=result.marks;
 if(newRole)s.role=newRole;
 if(newTeam)s.team=newTeam;
 if(fit!==undefined)s.fit=fit;
 Object.assign(s.flags,flags);
 const entries=[];
 if(money)for(const op of money)book(s,op,entries);
 if(trophy){s[trophy]++;s.titles++;book(s,["earn",trophy==="world"?50:10,trophy==="world"?"世界冠军奖金":"赛区冠军奖金"],entries);
  if(trophy==="world"&&s.flags.deal==="bet")book(s,["earn",70,"夺冠对赌兑现"],entries);
  if(trophy==="world"&&s.flags.deal==="equity")book(s,["earn",10,"5% 股份分红"],entries);
 }
 const entry={turn:s.turn,index:i,age:ages[s.turn-1],title:event.title,choice:c.title,text:result.text,delta,odds,roll,win,role:s.role,team:s.team,ending:result.ending,snapshot,entries,trophy:trophy||"",art:result.art||"",target:c.target||"行动成功"};
 s.history.push(entry);
 s.pending=true;
 return true;
}
function advance(s){
 if(!s.pending||s.end)return false;
 const entry=s.history[s.history.length-1];
 if(entry.ending){s.end=entry.ending;s.pending=null;return true;}
 if(s.turn===30)throw Error("末轮缺少结局");
 const routine=routines[s.turn];
 if(routine){
   const [note,delta]=routine(s);
   entry.routine={note,delta:apply(s,delta)};
 }
 s.turn++;s.pending=null;
 return true;
}
