function newAccount(){return {income:0,debt:0,cash:0};}
function book(s,[type,amount,note],log){
 const a=s.account;
 let value=amount;
 if(type==="earn"){a.income+=value;a.cash+=value;}
 else if(type==="borrow"){a.cash+=value;a.debt+=value;}
 else if(type==="repay"){value=Math.min(a.cash,a.debt,amount);a.cash-=value;a.debt-=value;}
 else if(type==="spend"){if(a.cash<value)throw Error("资金不足");a.cash-=value;}
 else throw Error("未知账目");
 if(value)log.push({type,value,note});
}
