const baseByRound={1:[66,45,76],2:[42,61,79],3:[38,64,78,54],4:[79,38,58],5:[77,55,36,29],6:[33,76],7:[76,48],8:[34,78,49],9:[35,68,48,57],10:[42,76],13:[80,54,33,70],14:[78,51,32],15:[76,45],17:[74,48],19:[49,77],20:[61,73,43,81],21:[81,48],24:[49,83,28,34,75],25:[75,46],26:[72,46],27:[74,56,39,31],28:[43,79],29:[71,42],30:[61,75,47,80]};
const contestRounds=new Set([6,11,12,16,17,22,23,25,26]);
function resolveOption(s,c,i){
 if(c.base!==undefined)return c;
 const base=baseByRound[s.turn]?.[i]??58;
 if(c.weights){
  const trial=s.turn===9&&s.flags.plan==="switch";
  const transferBase={上单:39,打野:27,中单:33,下路:48,辅助:62};
  return {...c,base:trial?transferBase[c.success.marks.newRole]:base,icon:s.turn===6?"strike":"route",target:trial?"转位成功":"行动成功",contest:s.turn===6};
 }
 const [target,yes,no]=(c.result.ending?farewellBeat(c.result.ending):null)||intervalNotes[s.turn]||["争取额外训练时间","有队友为你多留了一副耳机。","训练表已经排满，额外的约定要往后挪。"];
 const original=c.result,benefit=base<=45?4:2;
 const relevant=[1,2,4,7,14,15,17,19,20,26,29,30].includes(s.turn)?1:s.turn===21?3:2;
 function branch(win){
  const delta=STATS.map((_,j)=>(original.delta[j]||0)+(j===relevant&&win?benefit:0));
  return {...original,text:original.text+" "+(win?yes:no),delta};
 }
 return {...c,icon:c.icon||"",base,weights:STATS.map((_,j)=>j===relevant?3:0),target,success:branch(true),failure:branch(false),bonus:0,contest:false};
}
function stageName(s){
 if(s.turn===15&&s.flags.outside==="fixed"||s.turn===25&&s.flags.stake==="fraud")return "生涯 · 调查与告别";
 if(s.turn===15&&s.flags.seedA)return "世界城 · 八强赛";
 if(s.turn===16&&s.flags.qA===false||s.turn===25&&s.flags.qB===false)return "世界城 · 八强离席";
 if(s.turn<=5)return "青训期";
 if([11,22].includes(s.turn))return "赛区联赛 · 半决赛";
 if(s.turn===12||s.turn===23)return (s.turn===12?s.flags.semiA:s.flags.semiB)?"赛区联赛 · 决赛":"赛区联赛 · 末席资格战";
 if(s.turn===16||s.turn===25)return (s.turn===16?s.flags.seedA:s.flags.seedB)?"世界城 · 世界半决赛":"休赛期 · 世界赛观战";
 if(s.turn===17||s.turn===26)return (s.turn===17?s.flags.finalA:s.flags.finalB)?"世界城 · 世界决赛":"休赛期 · 散场之后";
 if(s.turn===18)return "转会窗口";if(s.turn===24)return "赛前假期";
 return chapter(s);
}
function sceneRecord(s,e){
 return {title:e.title,body:e.body,art:e.art,stage:stageName(s),options:e.options.map(c=>({title:c.title,hint:c.hint,icon:c.icon||"",target:c.target,odds:chance(s,c),bonus:c.bonus||0,reason:c.reason||"",weights:c.weights,fit:c.contest?s.fit:0}))};
}
function getScene(s){
 let e;
 switch(s.turn){
 case 11:case 22:e=districtSemi(s,s.turn===22);break;
 case 12:case 23:e=districtClose(s,s.turn===23);break;
 case 15:e=s.flags.seedA&&s.flags.outside!=="fixed"?quarterfinal(s):chapters[14](s);break;
 case 16:e=worldSemi(s,false);break;
 case 17:e=s.flags.finalA?worldFinal(s,false):aftermath(s,false);break;
 case 18:e=contractNight(s);break;
 case 19:e=titleWithThisTeam(s)?championRoom(s):chapters[18](s);break;
 case 24:e=investment(s);break;
 case 25:e=s.flags.stake==="fraud"?chapters[24](s):worldSemi(s,true);break;
 case 26:e=s.flags.finalB?worldFinal(s,true):aftermath(s,true);break;
 default:e=chapters[s.turn-1](s);
 }
 if(s.turn===3){
  const grants=[2,3,1,2];
  e.options.forEach((c,i)=>{c.icon="contract";c.hint+=" 青训补贴 "+grants[i]+" 万。";c.result.marks.money=[["earn",grants[i],"青训补贴"]];});
 }
 if(s.turn===5){
  e.art="night";e.options[1].hint="周末值班，领 1 万勤工补贴。";e.options[1].result.marks.money=[["earn",1,"值班补贴"]];
  e.options.push(pick("借 3 万报封闭训练班","无息借款 3 万全额付学费，入账后可择机还款。",outcome("你把借据压在课表下面。晚上十一点，只剩你这排机器还亮着。",[4,0,2,-2],{home:"loan",money:[["borrow",3,"训练借款"],["spend",3,"封闭训练学费"]]})));
 }
 if(s.turn===6){
  if(s.flags.home==="family")e.body+=" 往看台望去，昨天听你用杯子摆过阵型的那个人先站了起来。";
  e.options[0].success.marks.money=[["earn",5,"首秀高光奖金"]];e.options[0].hint="首秀高光另奖 5 万，也可能把机会让给对面。";
  const safe=e.options[1];e.options[1]=shot(safe.title,"保住阵形，为队伍争取首胜。","guard",76,voices,safe.result,outcome("你退回了搭档身边，比赛却在另一侧结束。散场时搭档把两副耳机放到一起，说好明天重听。",[0,1,1,0],{first:"miss"}));
 }
 if(s.turn===13&&s.account.debt&&s.account.cash){
  const n=Math.min(s.account.debt,s.account.cash);
  e.options.push(pick("先还 "+n+" 万，再去取体检单","按现有现金归还欠款，保留体检安排。",outcome("转账到账以前，你一直没松开手机。拿到体检单时，指尖才慢慢放松。",[0,1,0,2],{off:"health",money:[["repay",n,"归还借款"]]})));
 }
 if(s.turn===14&&s.flags.off==="offer"){e.art="cash";e.options[2].title="收下 20 万，替对方改写比分";e.options[2].hint="非法款项将被追缴，赛果会被调查。";e.options[2].result.marks.money=[["borrow",20,"待追缴非法款"]];}
 if(s.turn===29&&s.account.debt&&s.account.cash){
  const n=Math.min(s.account.cash,s.account.debt);
  e.options.push(pick("拿出 "+n+" 万，先归还借款","用现有现金还款，之后再给新人上最后一课。",outcome("回执上的数字终于变小了。你把借据锁进抽屉，再拉开训练室的门。",[0,2,0,2],{legacy:"handdown",money:[["repay",n,"生涯末期还款"]]})));
 }
 if(s.turn===28&&s.flags.intent==="owner"&&s.flags.stake==="clean"){
  e.options[0].success.marks.money=[["earn",6,"训练馆经营分红"]];e.options[0].hint+=" 经营有成，另得 6 万分红。";
 }
 if(s.turn===15&&s.flags.outside==="fixed"){e.art="caseFile";for(const c of e.options)c.result.marks.money=[["repay",20,"追缴非法款"]];}
 if(s.turn===25&&s.flags.stake==="fraud"){e.art="caseFile";e.options[0].result.marks.money=[["repay",40,"返还集训款"]];}
 if(s.turn===15&&s.flags.outside==="leak"&&!s.flags.seedA)e.art="row";
 if(s.turn===1){
  e.title="录像里，有个人没说完";
  e.body="电话那头没有寒暄。教练放了一段五人训练的录音。两个人同时喊了相反的方向，他按下暂停。窗外的自行车铃恰好响了一声。\n\n“刚才，你先听见什么？”";
 }
 if(s.turn===2)e.body="训练室剩最后一小时。有人拉椅子做对练，有人一遍遍倒带，角落里两个人在练一句总是说迟的口令。教练把备用耳机递给你：“去坐吧。”";
 if(s.turn===4)e.body="大灯熄了，训练室只剩三块屏幕。陪你一周的人已经把两把椅子拉在一起。新来的试训生手更快，还站在门口。明早的搭档名单，你也有一票。";
 if(s.turn===8)e.body="首发席上多贴了一张名牌。新人来借鼠标垫，很小心地没碰到你那一块。教练把三把钥匙摆在桌上：另一条路，一张替补席，或者明天的对练。";
 if(s.turn===13)e.body=(s.flags.seedA?"通行证装进口袋的第一个周末。":"落选后的第一个周末。")+"宿舍的晾衣架上还挂着队服。体检室催你拿报告，有人想听你公开讲一场败局，还有个熟人只肯当面说价钱。";
 if(s.turn===21)e.body="赶车那天，队医把体检单夹在首发名单里。"+(s.stats[3]<55?"手指有点沉，翻页时你试了第二次。":"你顺手替新人提了包，才发现他一直在看你的手腕。")+"替补已经热好了手，车上给两个人都留了座位。";
 if(s.turn===10)entranceChoices(e);
 if(s.turn===24&&s.flags.seedB){
  e.body+=" 世界城的八强名单已经发来。假期过后，整轮赛事将独立结算。";
  e.options.push({...shot("谢绝投资，赶回场上亲自守一局","守住这一波可能完成自我救赎；系列赛仍另行判定。","flash",47,hand,
   outcome("你把合同退回去。八强开打时，对面在同一个窄口等你；你守住了自己的那波。",[3,1,1,-1],{stake:"none",lastStandB:true}),
   outcome("你赶回了训练席。那一波没有留下对面的主攻手。",[1,1,0,-1],{stake:"none"})),target:"守住这一局"});
 }
 if(s.turn===27&&titleWithThisTeam(s)){
  e.body+=" 庆功照还在墙上，管理层只肯为四名旧队员续约。有人把两份不同的名单推到了你面前。";
  e.options.push(pick("拒绝拆队，和冠军队解约","不愿拆散一起夺冠的阵容，选择离开。",outcome("最后一支笔放下，你把奖杯留给旧队。",[0,1,0,1],{},"splitChampion")));
  e.options.push(pick("放下试职，再请五个人回来谈","继续做选手，把队内协商带到下一次公开课。",outcome("五个人都肯回来听。你先把自己的失误放在第一轨。",[0,3,0,1],{intent:"player",champConflict:"mended"})));
 }
 addEndingDoors(s,e);
 e.options=e.options.map((c,i)=>resolveOption(s,c,i));
 if((s.turn===15&&s.flags.seedA&&s.flags.outside!=="fixed")||(s.turn===24&&s.flags.seedB)){
  e.options.forEach((c,i)=>{
   const stake=c.success.marks.stake;if(stake==="fraud")return;
   const a=seriesChance(s,s.turn===24,i,true,stake),b=seriesChance(s,s.turn===24,i,false,stake);
   c.hint+=a===b?" 系列赛晋级 "+a+"%。":" 系列赛晋级：本项达成 "+a+"%，未达成 "+b+"%。";
  });
 }
 return e;
}

