function fitsStage(q,stage){
 const context=q.body.slice(0,22);
 if(/世界八强|八强/.test(context))return stage.includes("八强");
 if(/世界决赛/.test(context))return stage==="世界决赛";
 if(/半决赛/.test(context))return stage.includes("半决赛");
 if(/决赛/.test(context))return stage.includes("决赛")&&!stage.includes("半决赛");
 if(/第五局|第五把|第四局|决胜局/.test(context))return /半决赛|决赛|八强|席位/.test(stage);
 return true;
}
function stageTactic(s,phase,stage,forced){
 const role=s.role||"中单",seen=new Set(s.history.map(h=>h.tactic).filter(Boolean));
 const bank=BANK[role],eligible=bank.filter(q=>fitsStage(q,stage)),pool=eligible.length?eligible:bank,unused=pool.filter(q=>!seen.has(q.id));let choices=unused.length?unused:pool;
 const same=choices.filter(q=>q.caseId===s.flags.route),lane=choices.filter(q=>q.beat===phase),preferred=same.filter(q=>q.beat===phase);
 choices=preferred.length?preferred:same.length?same:lane.length?lane:choices;
 if(forced)return pool.find(q=>q.id===forced)||choices[0];
 const branch=s.history.reduce((n,h)=>(Math.imul(n,33)+h.index+(h.win?5:1))>>>0,0);
 return choices[(sampleNumber(s,s.turn+branch)%choices.length)];
}

