 if(h.turn===9&&f.seat==="switched")pics.push("switchrole");
 if([17,26].includes(h.turn)&&!h.trophy&&h.snapshot.stage==="世界决赛")pics.push("chair");

 if(h.turn===13&&f.social==="health")pics.push("wrist");
 if(h.turn===13&&f.social==="fans")pics.push("liverewind");
 if(h.turn===8&&f.plan==="bench")pics.push("sixth");
 if(h.turn===28&&f.intent==="coach")pics.push("coachboard");
 if(h.turn===28&&f.intent==="owner")pics.push("workshop");
 if(h.turn===14&&f.outside==="fixed")pics.push("cashdesk");
 if(h.turn===15&&f.outside==="fixed"||h.turn===25&&f.stake==="fraud")pics.push("books");
 if(h.turn===21&&f.load==="rest")pics.push("rehab");
 if(h.turn===28&&f.intent==="stream")pics.push("liverewind");
