function finishAs(s,requested){
 const f=s.flags, swapped=Boolean(f.firstRole&&f.firstRole!==s.role),bench=["scout","reserve","returned"].includes(f.seat)&&f.plan==="bench";
 const silver=s.history.some(h=>h.title&&h.target==="拿下这一局"&&!h.win&&(h.snapshot?.stage||"").includes("世界决赛"));
 switch(requested){
 case "stream":
  if(!s.titles&&f.selfRescue)return "redemptionLive";
  if(s.world)return "streamGold";
  if(silver)return "streamSilver";
  if(f.outside==="audience")return "streamOpen";
  break;
 case "player":
  if(s.world>=2)return "twinTitles";
  if(!s.titles&&f.selfRescue)return "wildcardRun";
  if(swapped)return "switchStarter";
  if(bench)return "benchVeteran";
  break;
 case "captain":
  if(f.deal==="duo")return "duoCaptain";
  if(s.regional&&!s.world)return "seedCaptain";
  break;
 case "coach":
  if(s.world)return "goldCoach";
  if(silver)return "silverCoach";
  if(swapped)return "switchCoach";
  if(bench)return "reserveCoach";
  break;
 case "owner":
  if(s.account.debt)return "debtClub";
  if(f.deal==="equity")return "equityClub";
  if(f.stake==="clean")return "academyClub";
  break;
 case "retire":
  if(s.world>=2)return "doubleFarewell";
  if(!s.world&&s.regional)return "regionalFarewell";
  break;
 case "nocup":
  if(f.selfRescue)return "eightFarewell";
  if(silver)return "silverFarewell";
  break;
 case "leave":if(f.home==="family")return "homeAgain";break;
 }
 return requested;
}

