const championEvents={
 "雷克顿":["top_bite","top_last"],"奥恩":["top_ornn","top_transfer"],"菲奥娜":["ts_race","top_fiora"],"蔚":[],"嘉文四世":["jg-play-8"],"千珏":["jg-play-16","jg-play-20"],"乐芙兰":["mid_lb"],"加里奥":["mid_galio"],"奥莉安娜":["mid_ball"],"劫":["mid_shadow"],"诺提勒斯":["mid_hook","mid_naut","duo_sup_04"],"维克托":["mid_viktor"],"阿狸":["mid_ahri"],"莫甘娜":["mid_morgwave","mid_shield"],"辛德拉":["mid_laneangle","mid_syndra"],"卢锡安":["duo_ad_10","duo_ad_11"],"艾希":["duo_ad_07"],"金克丝":[],"璐璐":["duo_sup_10","duo_sup_15"],"锤石":["duo_sup_08","duo_sup_11"]
};
function fitsMatch(q,s,stage){
 const line=q.title+" "+q.body,world=stage.startsWith("世界");
 if(q.id.startsWith("pair")&&!championEvents[s.flags.hero]?.includes(q.id))return false;
 if(/世界赛|世界八强|世界决赛/.test(q.body)&&!world)return false;
 if(/八强/.test(q.body)&&!stage.includes("八强"))return false;
 if(/半决赛/.test(q.body)&&!stage.includes("半决赛"))return false;
 if(/(^|[^半])决赛/.test(q.body)&&!["赛区决赛","世界决赛"].includes(stage))return false;
 if(/决胜局|第三局|第五局|第四局|前两局|连续两局|前四局|第三次/.test(line)&&!/(半决赛|决赛|席位|八强|淘汰赛)/.test(stage))return false;
 if(/争小组头名/.test(line)&&!stage.includes("小组"))return false;
 if(/重赛后|刚因故重开/.test(line)&&!s.flags.remake)return false;
 if(/换到打野的第一周/.test(line)&&!(s.flags.seat==="switched"&&s.role==="打野"))return false;
 if(["mid_botshift","mid_weakswap"].includes(q.id))return false;
 if(/旧版|老版本录像|盲选同一英雄/.test(line)&&!stage.includes("训练"))return false;
 return true;
}
function tacticStyle(q){
 if(/保护|护盾|反手|灯笼|黑盾|虚弱|击退|守家|门牙塔前|波比 W|留给突进/.test(q.title+" "+q.cue))return "guard";
 if(/兵线|炮车|补刀|印记|守塔|清线|发育|单带|主水晶|解线/.test(q.title+" "+q.cue))return "scale";
 return "strike";
}
function styleOfAction(o){
 if(/先补|补完|先清|收线|换线|先推|留在边|发育|换资源|换营地|拆塔/.test(o.label))return "scale";
 if(o.icon==="guard"||o.icon==="cleanse"||/留闪|保留|反打|先等/.test(o.label))return "guard";
 return "strike";
}
function stageTactic(s,phase,stage){
 const played=new Set(s.history.map(h=>h.tactic));
 const pool=BANK[s.role].filter(q=>fitsMatch(q,s,stage));
 const unused=pool.filter(q=>!played.has(q.id)),candidates=unused.length?unused:pool;
 const hero=heroFor(s),prefs=s.flags.preferences||{},partner=hero?.[2]||duoRole(s);
 const focus=s.flags.connection||partner;
 function score(q){
  const mode=tacticStyle(q),tag=championEvents[s.flags.hero]?.includes(q.id),salt=[...q.id].reduce((n,c)=>(n*31+c.charCodeAt(0))>>>0,0);
  const jitter=sampleNumber(s,salt+s.turn*131)%16;
  if(s.turn===7&&tag&&q.id.startsWith("pair"))return 60+jitter;
  return jitter+(q.beat===phase?3:0)+(tag?11:0)+(prefs[mode]||0)*1.2+partnerFit(s,focus,mode,s.team)+(focus==="打野"&&/野区|河道|绕后|打野|河口/.test(q.title+" "+q.cue)?5:0)+(focus==="下路"&&/射手|后排|保护|下路/.test(q.title+" "+q.cue)?5:0)+(focus==="辅助"&&/视野|侧面|入口|开团/.test(q.title+" "+q.cue)?5:0);
 }
 return candidates.reduce((a,b)=>score(a)>=score(b)?a:b);
}
function tactical(s,phase,stage,resolve,preface=""){
 const q=stageTactic(s,phase,stage),hero=heroFor(s),learnt=championEvents[s.flags.hero]?.includes(q.id),mate=teammate(s,s.team);
 const body=[preface,learnt&&hero?"这次选人拿回了练过的"+hero[0]+"。":"",q.body].filter(Boolean).join("\n\n");
 const options=q.options.map(o=>{
  const mode=styleOfAction(o),w=mode==="strike"?hand:mode==="guard"?voices:hours;
  const choiceIndex=q.options.indexOf(o);
  function result(ok){const info=resolve(ok,choiceIndex,q)||{};
   return outcome((ok?o.good:o.bad)+(info.text?" "+info.text:""),ok?[2,1,1,-1]:[1,0,1,-2],{...info.marks,approach:o.icon,practice:mode,...(o.link?{connection:o.link}:{})});}
  const c=decision(o.label,o.hint,o.icon,o.base,w,result(true),result(false),true,"拿下这一局");
  c.bonus=(learnt?3:0)+Math.min(4,Math.floor(s.flags.preferences?.[mode]||0))+partnerFit(s,o.link||hero?.[2]||duoRole(s),mode)+(o.link&&o.link===s.flags.connection?3:0)+(s.flags.prep==="review"?2:0);
  return c;
 });
 return scene(q.title,body,"match",options,{stage,tactic:q.id,official:!/训练|试训|合练/.test(stage),map:{zone:q.zone,red:q.red,blue:q.blue,cue:q.cue},lineup:mate?.name});
}
