 const momentHeader=e.art.startsWith("mem:");
 const main='<div class="career-feed">'+carry(s,h)+chatRows(h)+'<article class="next-decision"><header><p class="kicker">'+esc(e.stage)+'</p><h1>'+esc(e.title)+'</h1></header><div class="decision-copy"><p class="body-copy">'+esc(intro+e.body)+'</p>'+(!e.map&&!(momentHeader&&h?.photos?.includes(e.art.slice(4)))?img(eventArt(s,e.art),momentHeader?MEMORY[e.art.slice(4)].title:"本轮场景插画","decision-frame"):"")+'</div>'+tacticalBoard(e.map)+'<div class="choices">'+optionsHTML(e.options)+'</div></article></div>';
